<link rel="stylesheet" href="<?=asset('css/publishing.css')?>">
<main class="write-main pub-main">
  <div class="writer-head"><div><span class="writer-kicker">One story · Every channel</span><h1>Publishing centre</h1><p class="pub-lead">Prepare the week’s story, approve each version and follow every delivery through to its published link.</p></div><div class="writer-actions"><a class="wbtn primary" href="<?=url('/write/publishing/new')?>">New package</a></div></div>
  <nav class="pub-nav" aria-label="Publishing"><a href="<?=url('/write/media-centre')?>">Media centre & analytics</a><a href="<?=url('/write/publishing')?>" aria-current="page">Packages & calendar</a><a href="<?=url('/write/connections')?>">Connections</a><a href="<?=url('/write')?>">Article library</a></nav>
  <?php foreach(flashes() as $f):?><div class="notice <?=$f['type']==='error'?'error':''?>"><?=e($f['message'])?></div><?php endforeach;?>
  <?php $counts=['scheduled'=>0,'attention'=>0,'published'=>0];foreach($jobs as $job){if($job['status']==='scheduled')$counts['scheduled']++;elseif($job['status']==='published')$counts['published']++;elseif(in_array($job['status'],['assisted','reminder_queued','reminder_sent','failed','reconnect','ambiguous'],true))$counts['attention']++;}?>
  <section class="pub-stat-grid" aria-label="Recent delivery overview"><div class="pub-card"><span class="pub-number"><?=$counts['scheduled']?></span><strong>Scheduled</strong></div><div class="pub-card"><span class="pub-number"><?=$counts['attention']?></span><strong>Need a step</strong></div><div class="pub-card"><span class="pub-number"><?=$counts['published']?></span><strong>Completed in platform</strong></div></section>
  <p class="pub-help">Counts cover the most recent 100 delivery records. Release times use <?=e((string)app_config('timezone','Africa/Nairobi'))?>.</p>
  <section class="pub-section"><h2 class="pub-section-title">Your publication packages</h2><div class="pub-list">
    <?php if(!$packages):?><div class="pub-empty"><h2>Start with this week’s decision.</h2><p>Give it a title, add the article link and prepare the versions you want to share.</p><a class="wbtn primary" href="<?=url('/write/publishing/new')?>">Prepare the first package</a></div><?php endif;?>
    <?php foreach($packages as $package):?><article class="pub-row"><div><h3><a href="<?=url('/write/publishing/'.$package['id'])?>"><?=e($package['title'])?></a></h3><p>Draft version <?=intval($package['draft_version'])?> · <?=intval($package['job_count'])?> delivery records</p></div><div class="pub-row-meta"><span class="pub-status <?=$package['approved_revision_id']?'connected':''?>"><?=$package['approved_revision_id']?'Approved revision':'Draft'?></span><span>Updated <?=e(format_date($package['updated_at']))?></span></div></article><?php endforeach;?>
  </div></section>
  <section class="pub-section"><h2 class="pub-section-title">Delivery calendar & follow-up</h2><p>A reminder is a task to finish. “Accepted / processing” means the provider has the post; publication is a separate confirmation.</p><div class="pub-list">
    <?php if(!$jobs):?><div class="pub-empty"><p>Scheduled releases and assisted posting tasks will appear here after you approve a package and choose its release time.</p></div><?php endif;?>
    <?php foreach($jobs as $job):?><article class="pub-row"><div><h3><a href="<?=url('/write/publishing/'.$job['package_id'].'#deliveries')?>"><?=e($job['title'])?></a></h3><p><?=e($job['channel_name'])?> · <?=e(publishing_local_time($job['scheduled_at']))?></p><?php if($job['last_error']):?><p><?=e($job['last_error'])?></p><?php endif;?></div><div class="pub-row-meta"><span class="pub-status <?=e($job['status'])?>"><?=e(publishing_job_label($job))?></span><?php if($job['external_url']&&publishing_public_url($job['external_url'])):?><a href="<?=e($job['external_url'])?>" target="_blank" rel="noopener noreferrer">View post ↗</a><?php endif;?></div></article><?php endforeach;?>
  </div></section>
</main>
